'use strict';
// Singapore pilot only. Pantry selections are session-only and mean enough for the selected batch.
const pantryByRecipe = new Map();
let pantry = new Set();
function recipeTabs(){return [['ingredients','Ingredients'],['cook','Cook along'],['prep','Meal prep'],...(window.PRICE_ESTIMATES?.[active?.id]?[['costs','Costs']]:[])];}
function costEstimate(r,portions,owned=new Set(),catalog=window.PRICE_ESTIMATES?.[r.id]){
 if(!catalog)return null;
 const rows=r.ingredients.map(([quantity,unit,name],index)=>{
  if(catalog.excludedIngredients.includes(index))return {index,name,excluded:true};
  const item=catalog.items.find(p=>p.ingredient===index);
  if(!item||!Number.isFinite(item.packPrice)||item.packPrice<=0||!Number.isFinite(item.packQuantity)||item.packQuantity<=0||!Number.isFinite(item.quantityFactor)||item.quantityFactor<=0)return {index,name,missing:true};
  const needed=quantity*portions/r.servings*item.quantityFactor, packs=Math.ceil(needed/item.packQuantity-1e-10);
  return {...item,index,name,needed,packs,used:needed/item.packQuantity*item.packPrice,shopping:owned.has(index)?0:packs*item.packPrice,owned:owned.has(index)};
 });
 const known=rows.filter(x=>!x.excluded&&!x.missing), used=known.reduce((n,x)=>n+x.used,0),shopping=known.reduce((n,x)=>n+x.shopping,0);
 return {rows,used,shopping,perPortion:used/portions,complete:!rows.some(x=>x.missing)};
}
function money(n){return 'S$'+n.toFixed(2);}
function renderCosts(){
 const catalog=window.PRICE_ESTIMATES[active.id],c=costEstimate(active,servings,pantry),e=escapeHTML;
 $('#tab-content').innerHTML=`<section class="cost-section" aria-labelledby="cost-title"><div class="cost-intro"><div><p class="eyebrow">SHOPPING IN SINGAPORE · SGD</p><h3 id="cost-title">Plan your food budget.</h3><p>FairPrice pack prices for ${e(active.title.toLowerCase())}. Shopping location is separate from recipe cuisine.</p></div><div class="stepper"><button data-action="less" aria-label="Fewer portions" ${servings<=1?'disabled':''}>−</button><span>${servings} portion${servings===1?'':'s'}</span><button data-action="more" aria-label="More portions" ${servings>=8?'disabled':''}>+</button></div></div><div class="cost-totals" aria-live="polite"><article class="cost-primary"><span>${c.complete?'Estimated cost / portion':'Known cost / portion · incomplete'}</span><strong>${money(c.perPortion)}</strong><p>Based on quantities used, including pantry ingredients.</p></article><article><span>${c.complete?'Ingredients used · whole batch':'Known ingredients · subtotal'}</span><strong>${money(c.used)}</strong><p>The value of the food used for ${servings} portion${servings===1?'':'s'}.</p></article><article><span>${c.complete?'Estimated shopping spend':'Shopping subtotal · incomplete'}</span><strong>${money(c.shopping)}</strong><p>Whole packs to buy after your pantry selections. Leftovers remain for other meals.</p></article></div><p class="cost-snapshot"><strong>Price snapshot · retrieved ${e(catalog.retrievedAt)}.</strong> ${e(catalog.sourceStatus)} Regular single-pack prices, without offers or delivery.</p><div class="cost-list-heading"><h4>What you’ll need to buy</h4><p>Tick “Already have this” only if you have enough for all ${servings} portions. This lowers shopping spend, not the ingredient value. Selections reset on page reload.</p></div><div class="cost-items">${c.rows.filter(x=>!x.excluded).map(x=>x.missing?`<article class="cost-item"><h4>${e(x.name)}</h4><p>Price unavailable — excluded from the subtotal, not counted as free.</p></article>`:`<article class="cost-item ${x.owned?'in-pantry':''}"><div><h4>${e(x.name)}</h4><p>${+x.needed.toFixed(1)} ${e(x.unit)} used · <b>${money(x.used)}</b></p><small>${e(x.product)} · ${x.packQuantity} ${e(x.unit)} pack · ${money(x.packPrice)}</small>${x.assumption?`<small class="cost-assumption">${e(x.assumption)}</small>`:''}<a href="${e(x.sourceUrl)}" target="_blank" rel="noopener">FairPrice source ↗</a></div><div class="cost-buy"><b>${x.owned?'From your pantry':`${x.packs} pack${x.packs===1?'':'s'} · ${money(x.shopping)}`}</b><label><input type="checkbox" data-pantry="${x.index}" ${x.owned?'checked':''}> Already have this<span class="sr-only">: ${e(x.name)}</span></label></div></article>`).join('')}</div><details class="cost-notes"><summary>How this estimate works</summary><p>Ingredient value = quantity used ÷ pack size × pack price. Shopping spend rounds up to full packs. Totals use unrounded values, so displayed rows can differ by a cent when added.</p><p>${e(catalog.conversionNote)} Produce sizes and trimming can change how much you need to buy.</p><p>Excludes tap water, cooking energy, equipment, containers, delivery, service fees and extra food lost to trimming or spoilage. Pan, air fryer, rice cooker and vegetable methods use the same priced ingredients; energy costs are not compared.</p><p>Prices and stock can change. Check the source before shopping. This is a manually maintained pilot estimate, not a cheapest-basket claim or a FairPrice partnership.</p></details></section>`;
}
